"""Apply the rules from docs/DESIGN.md to results/raw_*.csv; write results/summary.csv, results/RESULTS_TABLES.md and one figure per architecture."""
import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1]))
import glob, pandas as pd, numpy as np, matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
from matplotlib.colors import ListedColormap
import config as C
d = pd.concat([pd.read_csv(f) for f in sorted(glob.glob(str(C.RES / "raw_*.csv")))], ignore_index=True); d["passed"] = d.passed.astype(bool)
fp = d[d.tech == "fp"].set_index(["arch", "seed", "method"])[["forget_score", "retain_ratio", "passed"]]; q = d[d.tech != "fp"].join(fp, on=["arch", "seed", "method"], rsuffix="_fp")
q["same_as_fp"] = ((q.forget_score - q.forget_score_fp).abs() <= C.SAME_SCORE) & (q.retain_ratio <= q.retain_ratio_fp + C.SAME_RETAIN); q["stuck"] = q.changed < C.STUCK_BELOW
rows = []
for (arch, tech, bits, method), s in q.groupby(["arch", "tech", "bits", "method"]):
    n = len(s); need = n // 2 + 1 if n > 2 else n; stuck = int(s.stuck.sum()); same = int((s.same_as_fp & ~s.stuck).sum())
    verdict = "stuck (<1% weights changed)" if stuck >= need else "moved"
    rows.append(dict(arch=arch, tech=tech, bits=bits, method=method, seeds=n, median_changed=round(s.changed.median(), 4), seeds_stuck=stuck, seeds_same_as_fp=same, median_forget_score=round(s.forget_score.median(), 2),
                     median_forget_score_fp=round(s.forget_score_fp.median(), 2), median_retain_ratio=round(s.retain_ratio.median(), 2), seeds_passed_strict_rule=int(s.passed.sum()), seeds_fp_passed=int(s.passed_fp.sum()), verdict=verdict))
S = pd.DataFrame(rows); S.to_csv(C.RES / "summary.csv", index=False)
fpt = d[d.tech == "fp"].groupby(["arch", "method"]).agg(median_forget_score=("forget_score", "median"), median_retain_ratio=("retain_ratio", "median"), seeds_passed=("passed", "sum"), memorization_gap=("gap", "median")).round(2)
md = ["# Results tables (generated by steps/05_report.py)\n", "Full-precision reference (same fixed settings, no quantization):\n", fpt.reset_index().to_markdown(index=False), ""]
col = {"stuck (<1% weights changed)": 0, "moved": 1.0}
for arch in C.ARCHS:
    A = S[S.arch == arch]
    if A.empty: continue
    md += [f"\n## {arch}: how many of the {A.method.nunique()} methods end in each state, per quantization technique and bit width\n"]
    t = A.groupby(["tech", "bits", "verdict"]).size().unstack(fill_value=0).reindex(columns=list(col), fill_value=0).reset_index(); t["bits"] = t.bits.astype(int)
    t["tech"] = t.tech.map(lambda k: C.QUANT[k][0]); md += [t.sort_values(["tech", "bits"], ascending=[True, False]).to_markdown(index=False), ""]
    md += [f"Median fraction of integer weights changed (%), {arch}:\n", A.pivot_table(index=["tech", "method"], columns="bits", values="median_changed", aggfunc="first").mul(100).round(1)[sorted(C.BITS, reverse=True)].to_markdown(), ""]
    fig, axs = plt.subplots(1, 3, figsize=(15, 3.8), sharey=True); meths = list(C.METHODS)
    for ax, tech in zip(axs, C.QUANT):
        B = A[A.tech == tech]; M = np.full((len(meths), len(C.BITS)), np.nan); T = [[""] * len(C.BITS) for _ in meths]
        for i, mth in enumerate(meths):
            for j, b in enumerate(sorted(C.BITS, reverse=True)):
                r = B[(B.method == mth) & (B.bits == b)]
                if len(r): M[i, j] = col[r.verdict.iloc[0]]; T[i][j] = f"{r.median_changed.iloc[0]*100:.0f}%"
        ax.imshow(M, cmap=ListedColormap(["#c0392b", "#e0a030"]), vmin=0, vmax=1, aspect="auto")
        for i in range(len(meths)):
            for j in range(len(C.BITS)): ax.text(j, i, T[i][j], ha="center", va="center", color="white", fontsize=8, fontweight="bold")
        ax.set_xticks(range(len(C.BITS))); ax.set_xticklabels([f"INT{b}" for b in sorted(C.BITS, reverse=True)]); ax.set_yticks(range(len(meths))); ax.set_yticklabels(meths, fontsize=8); ax.set_title(C.QUANT[tech][0], fontsize=9)
    fig.suptitle(f"{arch}: unlearning a quantized model with integer weights only. red = integer weights stuck (<1% changed), amber = weights moved (this does not mean the forgetting was correct). text = % of integer weights changed", fontsize=8)
    plt.tight_layout(); plt.savefig(C.FIG / f"{arch}.png", dpi=140); plt.close()
open(C.RES / "RESULTS_TABLES.md", "w").write("\n".join(md)); print("\n".join(md[:60]))
